<script setup>
import { computed, onMounted, ref } from "vue"
import { getInventorySnapshot, getProductionPlanSnapshot, getWorkspaceSnapshot, resolveScanCode } from "@/resources/api"
import AccountantExport from "@/blocks/accountant-export/AccountantExport.vue"
import BulkbiteAppShell from "@/blocks/bulkbite-app-shell/BulkbiteAppShell.vue"
import DocumentReview from "@/blocks/document-review/DocumentReview.vue"
import ProductionMeasurement from "@/blocks/production-measurement/ProductionMeasurement.vue"
import ReceiptIntake from "@/blocks/receipt-intake/ReceiptIntake.vue"
import StockOverview from "@/blocks/stock-overview/StockOverview.vue"
import StockReconciliation from "@/blocks/stock-reconciliation/StockReconciliation.vue"

const sections = [
  { id: "overview", number: "01", label: "Stock" },
  { id: "receipts", number: "02", label: "Receipts" },
  { id: "production", number: "03", label: "Production" },
  { id: "documents", number: "04", label: "Worker sheets" },
  { id: "counts", number: "05", label: "Stock count" },
  { id: "export", number: "06", label: "Accountant export" },
]
const activeSection = ref(new URLSearchParams(window.location.search).get("work") || "overview")
const snapshot = ref(null)
const inventory = ref(null)
const plan = ref(null)
const scanResult = ref(null)
const loading = ref(false)
const error = ref("")
const currentUser = computed(() => snapshot.value?.user || window.boot?.user || "")

function navigate(id) {
  activeSection.value = id
  const url = new URL(window.location.href)
  id === "overview" ? url.searchParams.delete("work") : url.searchParams.set("work", id)
  window.history.replaceState({}, "", url)
  requestAnimationFrame(() => document.querySelector(".app-shell__work")?.focus())
}

async function loadAll() {
  loading.value = true; error.value = ""
  try {
    const [workspaceData, inventoryData, planData] = await Promise.all([getWorkspaceSnapshot(), getInventorySnapshot("Ingredients"), getProductionPlanSnapshot(null, "Ingredients")])
    snapshot.value = workspaceData; inventory.value = inventoryData; plan.value = planData
  } catch (exception) { error.value = exception.message } finally { loading.value = false }
}

async function scan(code) { error.value = ""; try { scanResult.value = await resolveScanCode(code) } catch (exception) { error.value = exception.message } }
onMounted(loadAll)
</script>

<template>
  <BulkbiteAppShell :sections="sections" :active-section="activeSection" :user="currentUser" :busy="loading" @navigate="navigate" @refresh="loadAll">
    <StockOverview v-if="activeSection === 'overview'" :snapshot="snapshot" :inventory="inventory" :plan="plan" :scan-result="scanResult" :loading="loading" :error="error" @scan="scan" @open-workflow="navigate" />
    <ReceiptIntake v-else-if="activeSection === 'receipts'" :snapshot="snapshot" :inventory="inventory" @changed="loadAll" />
    <ProductionMeasurement v-else-if="activeSection === 'production'" :snapshot="snapshot" :plan="plan" @changed="loadAll" />
    <DocumentReview v-else-if="activeSection === 'documents'" :snapshot="snapshot" :inventory="inventory" @changed="loadAll" />
    <StockReconciliation v-else-if="activeSection === 'counts'" :inventory="inventory" @changed="loadAll" />
    <AccountantExport v-else-if="activeSection === 'export'" />
  </BulkbiteAppShell>
</template>
